<?php
require 'config.php'; require_role('student');
try{$pdo->exec("ALTER TABLE tickets MODIFY status ENUM('Open','In Progress','Ongoing','Resolved','Rejected') NOT NULL DEFAULT 'Open'");$pdo->exec("UPDATE tickets SET status='Ongoing' WHERE status='In Progress'");$pdo->exec("ALTER TABLE tickets MODIFY status ENUM('Open','Ongoing','Resolved','Rejected') NOT NULL DEFAULT 'Open'");}catch(PDOException $e){}
$title='My Ticket';$u=$_SESSION['user'];$msg='';$error='';
try{$pdo->exec("CREATE TABLE IF NOT EXISTS ticket_updates(id INT AUTO_INCREMENT PRIMARY KEY,ticket_id INT NOT NULL,status VARCHAR(30) NOT NULL,note VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE,INDEX(ticket_id,created_at))");}catch(PDOException $e){}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['create_ticket'])){
 $subject=trim($_POST['title']??'');$description=trim($_POST['description']??'');
 if($subject===''||$description==='')$error='Please complete the ticket subject and description.';else{$no='#TCK-'.date('ymd').'-'.random_int(1000,9999);$q=$pdo->prepare('INSERT INTO tickets(ticket_no,student_id,title,description) VALUES(?,?,?,?)');$q->execute([$no,$u['id'],$subject,$description]);$id=(int)$pdo->lastInsertId();try{$pdo->prepare('INSERT INTO ticket_updates(ticket_id,status,note) VALUES(?,?,?)')->execute([$id,'Submitted','Ticket created by student.']);}catch(PDOException $e){}log_transaction($pdo,(int)$u['id'],'Ticket Created',$subject.' ('.$no.')','ticket',$id);notify_user($pdo,(int)$u['id'],'Ticket submitted','Your ticket '.$no.' has been received by Administration.','Ticket');$msg='Ticket created successfully.';}}
try{$pdo->exec("INSERT INTO ticket_updates(ticket_id,status,note) SELECT t.id,'Submitted','Ticket created before timeline tracking was added.' FROM tickets t LEFT JOIN ticket_updates u ON u.ticket_id=t.id WHERE u.id IS NULL");}catch(PDOException $e){}
$sort=$_GET['sort']??'newest';if(!in_array($sort,['newest','oldest'],true))$sort='newest';$status=$_GET['status']??'all';if(!in_array($status,['all','Open','Ongoing','Resolved','Rejected'],true))$status='all';$search=trim($_GET['q']??'');$order=$sort==='oldest'?'ASC':'DESC';
$sql="SELECT * FROM tickets WHERE student_id=?";$params=[$u['id']];if($status!=='all'){$sql.=' AND status=?';$params[]=$status;}if($search!==''){$sql.=' AND (title LIKE ? OR description LIKE ? OR ticket_no LIKE ?)';$like='%'.$search.'%';array_push($params,$like,$like,$like);}$sql.=" ORDER BY created_at $order,id $order";$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
$ev=$pdo->prepare('SELECT * FROM ticket_updates WHERE ticket_id=? ORDER BY created_at ASC');
require 'header.php';?>
<?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="danger"><?=e($error)?></div><?php endif;?>
<div class="section"><h2>Create New Ticket</h2><form method="post" class="ticket-form"><input name="title" placeholder="Ticket subject" required><textarea name="description" placeholder="Describe your concern..." required></textarea><button class="btn" name="create_ticket">Create Ticket</button></form>
<div class="ticket-list-head"><h2 class="mt">My Tickets</h2><div class="ticket-tools"><form method="get" class="sort-form"><input name="q" value="<?=e($search)?>" placeholder="Search tickets"><select name="status"><option value="all" <?=$status==='all'?'selected':''?>>All statuses</option><option value="Open" <?=$status==='Open'?'selected':''?>>Open</option><option value="Ongoing" <?=$status==='Ongoing'?'selected':''?>>Ongoing</option><option value="Rejected" <?=$status==='Rejected'?'selected':''?>>Rejected</option><option value="Resolved" <?=$status==='Resolved'?'selected':''?>>Resolved</option></select><select name="sort"><option value="newest" <?=$sort==='newest'?'selected':''?>>Newest posted</option><option value="oldest" <?=$sort==='oldest'?'selected':''?>>Oldest posted</option></select><button class="btn" type="submit">Filter</button></form></div></div>
<?php if(!$rows):?><p class="muted">No tickets match your filters.</p><?php endif;?>
<?php foreach($rows as $r):$ev->execute([$r['id']]);$events=$ev->fetchAll();?><div class="ticket ticket-expanded"><div class="card-head"><div><b><?=e($r['title'])?></b><p class="muted"><?=e($r['ticket_no'])?> · <?=e($r['office'])?> · Posted <?=date('M d, Y · g:i A',strtotime($r['created_at']))?></p></div><span class="badge <?=str_replace(' ','-',strtolower($r['status']))?>"><?=e($r['status'])?></span></div><p><?=nl2br(e($r['description']))?></p><details class="ticket-status-dropdown"><summary><span>Ticket Status</span><span class="ticket-status-chevron" aria-hidden="true">⌄</span></summary><div class="timeline"><div class="timeline-label">Ticket Status Timeline</div><?php foreach($events as $i=>$event):?><div class="timeline-item"><span class="timeline-marker"></span><div><b><?=e($event['status'])?></b><?php if($event['note']):?><p><?=e($event['note'])?></p><?php endif;?><small class="muted"><?=date('M d, Y · g:i A',strtotime($event['created_at']))?></small></div></div><?php endforeach;?></div></details></div><?php endforeach;?></div>
<?php require 'footer.php';?>
